// spec: specs/auth.md (2.1)
// seed: tests/seed.spec.ts
// Гость. Кнопки Apple/Google НЕ нажимаются (внешние окна провайдеров), пароли не вводятся.

import { test, expect } from '@playwright/test';

const SCREENS = [
  { path: '/sign-up', title: 'יצירת חשבון' },
  { path: '/sign-in', title: 'כניסה' },
] as const;

const PROVIDERS = ['המשך עם Apple', 'המשך עם Google'] as const;

test.describe('Регистрация и вход — доступные имена кнопок провайдеров', () => {
  for (const screen of SCREENS) {
    test(`«${screen.title}» (${screen.path}): кнопки Apple и Google названы «המשך עם …», не «מתחברים…» #e653a0 @iphone @prod-safe`, async ({ page }) => {
      await page.goto(screen.path);

      for (const name of PROVIDERS) {
        const button = page.getByRole('button', { name, exact: true });
        // Ровно одна кнопка с этим доступным именем, видна
        await expect(button).toHaveCount(1);
        await expect(button).toBeVisible();
        // Доступное имя = видимая надпись (источник: «מה רצוי» #e653a0)
        await expect(button).toHaveAccessibleName(name);
        await expect(button).toHaveText(name);
        // Обычное состояние — не загрузка
        await expect(button).toBeEnabled();
        await expect(button).not.toHaveAttribute('aria-busy', 'true');
      }

      // «מתחברים…» — только во время входа; в обычном состоянии такой кнопки нет
      await expect(page.getByRole('button', { name: 'מתחברים' })).toHaveCount(0);
      await expect(page).toHaveURL(new RegExp(`${screen.path}$`));
    });
  }
});
